const s = (v) => String(v == null ? '' : v).trim();
const low = (v) => s(v).toLowerCase();
const norm = (x) => low(x).replace(/[^a-z0-9]/g, '');
// each target: the row we expect, the address to drop, and what must survive
const TARGETS = [
  { startup: 'Starz AI', row: 75, bad: 'admin@starzventure.com', note: '14 hard bounces, latest 19 Sep 2026' },
  { startup: 'Flyment', row: 34, bad: 'aditya.singh@flymentexpress.com', note: '6 hard bounces, latest 19 Sep 2026' },
  { startup: 'Recex', row: 44, bad: 'harsh@recex.co', note: '4 hard bounces, latest 19 Sep 2026' },
];
const rows = $input.all().map((i) => i.json);
const cols = Object.keys(rows[0]).filter((k) => k !== 'row_number');
const iE = cols.indexOf('Emails');
const iR = cols.findIndex((c) => low(c) === 'call remark');
if (iE < 0) throw new Error('Emails column not found');
const L = (i) => String.fromCharCode(65 + i);
const data = [];
const plan = [];
for (const t of TARGETS) {
  const hit = rows.filter((r) => r.row_number === t.row);
  if (hit.length !== 1) throw new Error('row ' + t.row + ' not found');
  const r = hit[0];
  if (norm(r['Startup']) !== norm(t.startup)) throw new Error('row ' + t.row + ' is ' + r['Startup'] + ', expected ' + t.startup);
  const before = s(r['Emails']);
  const parts = before.split(/[,;\s]+/).map(s).filter(Boolean);
  const kept = parts.filter((p) => low(p) !== low(t.bad));
  if (kept.length === parts.length) { plan.push({ startup: t.startup, row: t.row, action: 'noop - bad address not present', before }); continue; }
  if (kept.length === 0) throw new Error('refusing: removing ' + t.bad + ' would leave ' + t.startup + ' with no address');
  const after = kept.join(', ');
  data.push({ range: "'Founders Info'!" + L(iE) + t.row, values: [[after]] });
  if (iR >= 0) {
    const old = s(r[cols[iR]]);
    const remark = (old ? old + ' | ' : '') + 'Removed ' + t.bad + ' - ' + t.note + ' (checked 25 Sep 2026). Do not re-add.';
    data.push({ range: "'Founders Info'!" + L(iR) + t.row, values: [[remark]] });
  }
  plan.push({ startup: t.startup, row: t.row, action: 'remove', removed: t.bad, before, after });
}
return [{ json: { writes: data.length, plan, body: { valueInputOption: 'RAW', data } } }];
